import{_ as e,a0 as l,w as o,s as d,I as a,x as n,a1 as p,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse('{"title":"在 Ubuntu 16.04 上配置 msmtp | LCTT x X-CMD","titleTemplate":false,"description":"在 Ubuntu 16.04 上配置 msmtp | LCTT (201804) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"在 Ubuntu 16.04 上配置 msmtp | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"在 Ubuntu 16.04 上配置 msmtp | LCTT (201804) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201804/20180118 Configuring MSMTP On Ubuntu 16.04 (Again)","title":"在 Ubuntu 16.04 上配置 msmtp","tag":"201804","desc":""},"relativePath":"201804/20180118 Configuring MSMTP On Ubuntu 16.04 (Again).md","filePath":"[post].md"}'),u={name:"201804/20180118 Configuring MSMTP On Ubuntu 16.04 (Again).md"};function g(m,s,c,h,b,k){const t=l("Link");return o(),d("div",null,[s[16]||(s[16]=a("h1",{id:"在-ubuntu-16-04-上配置-msmtp",tabindex:"-1"},[n("在 Ubuntu 16.04 上配置 msmtp "),a("a",{class:"header-anchor",href:"#在-ubuntu-16-04-上配置-msmtp","aria-label":"Permalink to “在 Ubuntu 16.04 上配置 msmtp”"},"​")],-1)),s[17]||(s[17]=a("p",null,"這篇文章是在我之前的Blog中發表過的在 Ubuntu 16.04 上配置 MSMTP 的一個副本。我再次發表是為了後續，我並不知道它是否能在更高版本上工作。由於我沒有再託管自己的 Ubuntu/MSMTP 服務器了，所以我現在看不到有需要更新的地方，但是如果我需要重新設置，我會創建一個更新的帖子！無論如何，這是我現有的。",-1)),s[18]||(s[18]=a("p",null,"我之前寫了一篇在 Ubuntu 12.04 上配置 msmtp 的文章，但是正如我在之前的文章中暗示的那樣，當我升級到 Ubuntu 16.04 後出現了一些問題。接下來的內容基本上是一樣的，但 16.04 有一些小的更新。和以前一樣，這裏假定你使用 Apache 作為 Web 服務器，但是我相信如果你選擇其他的 Web 服務器，也應該相差不多。",-1)),a("p",null,[s[1]||(s[1]=n("我使用 ",-1)),p(t,{href:"http://msmtp.sourceforge.net/"},{default:i(()=>[...s[0]||(s[0]=[n("msmtp",-1)])]),_:1}),s[2]||(s[2]=n(" 發送來自這個Blog的郵件倆通知我評論和更新等。這裏我會記錄如何配置它通過 Google Apps 帳户發送電子郵件，雖然這應該與標準的 Google 帳户一樣。",-1))]),s[19]||(s[19]=r(`<p>首先，我們需要安裝 3 個軟件包：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt-get install msmtp msmtp-mta ca-certificates</span></span></code></pre></div><p>安裝完成後，就需要一個默認配置。默認情況下，msmtp 會在 <code>/etc/msmtprc</code> 中查找，所以我使用 <code>vim</code> 創建了這個文件，儘管任何文本編輯器都可以做到這一點。這個文件看起來像這樣：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Set defaults.</span></span>
<span class="line"><span>defaults</span></span>
<span class="line"><span># Enable or disable TLS/SSL encryption.</span></span>
<span class="line"><span>tls on</span></span>
<span class="line"><span>tls_starttls on</span></span>
<span class="line"><span>tls_trust_file /etc/ssl/certs/ca-certificates.crt</span></span>
<span class="line"><span># Setup WP account&#39;s settings.</span></span>
<span class="line"><span>account GMAIL</span></span>
<span class="line"><span>host smtp.gmail.com</span></span>
<span class="line"><span>port 587</span></span>
<span class="line"><span>auth login</span></span>
<span class="line"><span>user YOUR USERNAME</span></span>
<span class="line"><span>password YOUR PASSWORD</span></span>
<span class="line"><span>from FROM@ADDRESS</span></span>
<span class="line"><span>logfile /var/log/msmtp/msmtp.log</span></span>
<span class="line"><span></span></span>
<span class="line"><span>account default :</span></span></code></pre></div><p>任何大寫選項都是需要替換為你特定的配置。日誌文件是一個例外，當然你也可以將活動/警告/錯誤放在任何你想要的地方。</p><p>文件保存後，我們將更新上述配置文件的權限 ，如果該文件的權限過於開放，msmtp 將不會運行，並且創建日誌文件的目錄。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo mkdir /var/log/msmtp</span></span>
<span class="line"><span>sudo chown -R www-data:adm /var/log/msmtp</span></span>
<span class="line"><span>sudo chmod 0600 /etc/msmtprc</span></span></code></pre></div><p>接下來，我選擇為 msmtp 日誌配置 logrotate，以確保日誌文件不會太大並讓日誌目錄更加整潔。為此，我們創建 <code>/etc/logrotate.d/msmtp</code> 並使用按以下內容配置。請注意，這是可選的，你可以選擇不這樣做，或者你可以選擇以不同方式配置日誌。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/var/log/msmtp/*.log {</span></span>
<span class="line"><span>	rotate 12</span></span>
<span class="line"><span>	monthly</span></span>
<span class="line"><span>	compress</span></span>
<span class="line"><span>	missingok</span></span>
<span class="line"><span>	notifempty</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>現在配置了日誌，我們需要通過編輯 <code>/etc/php/7.0/apache2/php.ini</code> 告訴 PHP 使用 msmtp，並將 sendmail 路徑從</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sendmail_path =</span></span></code></pre></div><p>變成</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sendmail_path = &quot;/usr/bin/msmtp -C /etc/msmtprc -a -t&quot;</span></span></code></pre></div><p>這裏我遇到了一個問題，即使我指定了帳户名稱，但是當我測試它時，它並沒有正確發送電子郵件。這就是為什麼 <code>account default : </code> 這行被放在 msmtp 配置文件的末尾。要測試配置，請確保 PHP 文件已保存並運行 <code>sudo service apache2 restart</code>，然後運行 <code>php -a</code> 並執行以下命令</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mail (&#39;personal@email.com&#39;, &#39;Test Subject&#39;, &#39;Test body text&#39;);</span></span>
<span class="line"><span>exit();</span></span></code></pre></div><p>此時發生的任何錯誤都將顯示在輸出中，因此錯誤診斷會相對容易。如果一切順利，你現在應該可以使用 PHP sendmail（至少 WordPress 可以）中用 Gmail（或 Google Apps）從 Ubuntu 服務器發送電子郵件。</p><p>我沒有説這是最安全的配置，所以當你看到並且意識要這個非常不安全，或者有其他嚴重的錯誤，請讓我知道，我會相應地更新。</p><hr>`,18)),a("p",null,[s[4]||(s[4]=n("via: ",-1)),p(t,{href:"https://codingproductivity.wordpress.com/2018/01/18/configuring-msmtp-on-ubuntu-16-04-again/"},{default:i(()=>[...s[3]||(s[3]=[n("https://codingproductivity.wordpress.com/2018/01/18/configuring-msmtp-on-ubuntu-16-04-again/",-1)])]),_:1})]),a("p",null,[s[8]||(s[8]=n("作者：",-1)),p(t,{href:"https://codingproductivity.wordpress.com/author/joeb454/"},{default:i(()=>[...s[5]||(s[5]=[n("JOE",-1)])]),_:1}),s[9]||(s[9]=n(" 譯者：",-1)),p(t,{href:"https://github.com/geekpi"},{default:i(()=>[...s[6]||(s[6]=[n("geekpi",-1)])]),_:1}),s[10]||(s[10]=n(" 校對：",-1)),p(t,{href:"https://github.com/wxy"},{default:i(()=>[...s[7]||(s[7]=[n("wxy",-1)])]),_:1})]),a("p",null,[s[13]||(s[13]=n("本文由 ",-1)),p(t,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[11]||(s[11]=[n("LCTT",-1)])]),_:1}),s[14]||(s[14]=n(" 原創編譯，",-1)),p(t,{href:"https://linux.cn/"},{default:i(()=>[...s[12]||(s[12]=[n("Linux中國",-1)])]),_:1}),s[15]||(s[15]=n(" 榮譽推出",-1))])])}const y=e(u,[["render",g]]);export{T as __pageData,y as default};
